// pwa: SPAN service worker - offline play once the site has been opened over http(s).
// Registered by js/features/pwa.js (never on file://).
//  - install:  precaches every shipped game file (list + version generated by tools/gen-precache.js)
//  - activate: deletes older span-precache-* caches, takes control of open pages
//  - fetch:    index.html / navigations -> network-first (cached copy when offline or slow)
//              everything else (css, js, assets) -> cache-first, then network (and cached)
//  - update:   a new version waits until the page posts {type:'SKIP_WAITING'} (the "tap to reload" toast)
'use strict';

// <precache> generated by tools/gen-precache.js - do not edit by hand
