// </precache>

const PREFIX = 'span-precache-';
const CACHE = PREFIX + VERSION;
const NET_TIMEOUT_MS = 3500;
const scoped = p => new URL(p, self.registration.scope).href;
const INDEX = () => scoped('index.html');

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    // cache:'reload' skips the HTTP cache so a deploy never precaches a stale file
    await cache.addAll(PRECACHE.map(p => new Request(scoped(p), { cache: 'reload' })));
    // first install: nothing to replace, so activate straight away. Updates wait for the player.
    if (!self.registration.active) await self.skipWaiting();
  })());
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter(k => k.startsWith(PREFIX) && k !== CACHE).map(k => caches.delete(k)));
    await self.clients.claim();
  })());
});

self.addEventListener('message', event => {
  const d = event.data || {};
  if (d.type === 'SKIP_WAITING') self.skipWaiting();
  else if (d.type === 'GET_VERSION' && event.ports && event.ports[0]) {
    event.ports[0].postMessage({ version: VERSION, cache: CACHE, files: PRECACHE.length });
  }
});

function isPage(req, url) {
  if (req.mode === 'navigate') return true;
  const scope = new URL(self.registration.scope);
  return url.pathname === scope.pathname || url.pathname === scope.pathname + 'index.html';
}

async function networkFirst(req) {
  const cache = await caches.open(CACHE);
  const net = fetch(req).then(res => {
    if (res && res.ok && res.type === 'basic') cache.put(INDEX(), res.clone());
    return res;
  });
  try {
    // a slow mobile connection should not hold the game hostage: fall back to the cache after a while
    const res = await Promise.race([net, new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), NET_TIMEOUT_MS))]);
    if (res && res.ok) return res;
    const cached = await cache.match(INDEX());
    return cached || res;
  } catch (e) {
    const cached = await cache.match(INDEX());
    if (cached) { net.catch(() => {}); return cached; }
    return net; // nothing cached: let the network outcome (or error) through
  }
}

async function cacheFirst(req) {
  const cache = await caches.open(CACHE);
  const hit = await cache.match(req, { ignoreSearch: true });
  if (hit) return hit;
  try {
    const res = await fetch(req);
    if (res && res.ok && res.type === 'basic') cache.put(req, res.clone());
    return res;
  } catch (e) {
    return new Response('', { status: 504, statusText: 'Offline' });
  }
}

self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  if (url.pathname.endsWith('/sw.js')) return;
  event.respondWith(isPage(req, url) ? networkFirst(req) : cacheFirst(req));
});
